// Get all file extension
const fileExtension = $('Loop Over New Files').first().json.fileExtension.toLowerCase();
// $json.fullFileExtension.toLowerCase();
// Comprehensive file extension mappings
const fileCategories = {

  pdf: [
    'pdf'
  ],

  image: [
    'jpeg', 'png', 'webp', 'heic', 'heif'
  ],

  audio: [
    'mp3', 'wav', 'aiff', 'aac', 'ogg', 'flac',
  ],

  video: [
    'mp4', 'mpeg', 'mov', 'avi', 'x-flv', 'flv', 'mpg',
    'webm', 'wmv', '3gpp'
  ]
};

// Function to categorize file
function categorizeFile(extension) {
  for (const [category, extensions] of Object.entries(fileCategories)) {
    if (extensions.includes(extension)) {
      return category;
    }
  }
  return 'other';
}

  const category = categorizeFile(fileExtension);

  return {
    json: {
      category: category,
      extension: fileExtension,
    },
  };

